def get_relative_positions(grid):
    h, w = len(grid), len(grid[0])
    rmin, cmin = h, w
    rmax, cmax = -1, -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                rmin = min(rmin, r); cmin = min(cmin, c)
                rmax = max(rmax, r); cmax = max(cmax, c)

    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                rel_r, rel_c = r - rmin, c - cmin
                result.append((rel_r, rel_c))
    return sorted(result), (rmin, cmin, rmax, cmax)

