    """Find minimum steps to reach grid edge or empty cell"""
    visited = set([(r,c)])
    queue = [(r,c)]

    while queue:
        curr = queue.pop()
        cr, cc = curr
        # Check if neighbor is outside
        neighbors = [(cr+dr, cc+dc) for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]]
